import csv
import io
import re


def parse_csv(raw_csv: str):
    if not raw_csv:
        return {"columns": [], "rows": []}

    number = re.compile(
        r"[+-]?(?:(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?|inf(?:inity)?|nan)",
        re.IGNORECASE,
    )

    old_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > old_limit:
            csv.field_size_limit(len(raw_csv))
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), skipinitialspace=True))
    finally:
        csv.field_size_limit(old_limit)

    if not records:
        return {"columns": [], "rows": []}

    first = records[0]
    headerless = bool(first) and all(number.fullmatch(value.strip()) for value in first)

    if headerless:
        columns = []
        rows = records
    else:
        columns = list(first)
        rows = records[1:]

    width = max([3, len(columns)] + [len(row) for row in rows])
    used = set(columns)
    while len(columns) < width:
        index = len(columns) + 1
        name = f"column_{index}"
        while name in used:
            name += "_"
        columns.append(name)
        used.add(name)

    rows = [row + [""] * (width - len(row)) for row in rows]
    return {"columns": columns, "rows": rows}
